156	// Forces the freshly created key file to exactly 0600: owner read/write, no
157	// execute bit, no group/other access. The mode given to open() is still
158	// reduced by the inherited process umask, which can strip owner read (umask
159	// 0400), owner write (umask 0200), or both (umask 0600); fchmod() is not
160	// affected by the umask. The result is verified with fstat() so a filesystem
161	// that silently keeps different permissions is treated as a failure instead
162	// of being reported as a success.
163	bool fixKeyFilePermissions(int fd, const std::string& path,
164	                           std::string& error) {
165	    if (::fchmod(fd, S_IRUSR | S_IWUSR) != 0) {
166	        error = "cannot set key file permissions to 0600 on '" + path +
167	                "': " + errnoDescription(errno);
168	        return false;
169	    }
170	    struct stat info;
171	    if (::fstat(fd, &info) != 0) {
172	        error = "cannot verify key file permissions on '" + path +
173	                "': " + errnoDescription(errno);
174	        return false;
175	    }
176	    if ((info.st_mode & 0777) != (S_IRUSR | S_IWUSR)) {
177	        error = "cannot guarantee key file permissions 0600 on '" + path +
178	                "'";
179	        return false;
180	    }
181	    return true;
182	}
