285	int runKeygen(int argc, char* argv[]) {
286	    std::string outputPath;
287	    bool haveOutput = false;
288	
289	    for (int i = 2; i < argc; ++i) {
290	        std::string_view arg(argv[i]);
291	        if (arg == "--output") {
292	            if (haveOutput) {
293	                std::cerr << "envelopefile: '--output' specified more than "
294	                             "once\n"
295	                          << kKeygenUsage;
296	                return 2;
297	            }
298	            if (i + 1 >= argc) {
299	                std::cerr << "envelopefile: option '--output' requires a "
300	                             "non-empty path\n"
301	                          << kKeygenUsage;
302	                return 2;
303	            }
304	            outputPath = argv[++i];
305	            if (outputPath.empty()) {
306	                std::cerr << "envelopefile: option '--output' requires a "
307	                             "non-empty path\n"
308	                          << kKeygenUsage;
309	                return 2;
310	            }
311	            haveOutput = true;
312	        } else {
313	            std::cerr << "envelopefile: unsupported argument: '" << arg
314	                      << "'\n"
315	                      << kKeygenUsage;
316	            return 2;
317	        }
318	    }
319	
320	    if (!haveOutput) {
321	        std::cerr << "envelopefile: missing required option '--output'\n"
322	                  << kKeygenUsage;
323	        return 2;
324	    }
325	
326	    SecureBuffer key(kKeyBytes);
327	    std::string error;
328	    if (!generateKey(key, error)) {
329	        std::cerr << "envelopefile: " << error << '\n';
330	        return 1;
331	    }
332	
333	    const KeySaveResult save = writeKeyFile(outputPath, key.data(), key.size());
334	    if (!save.saved()) {
335	        // The save logic reports outcomes as data; the command line owns all
336	        // user-facing messages. The original failure is always the primary
337	        // cause; a failed cleanup is reported only as an additional warning,
338	        // never as a replacement, so the exit code stays 1 and the user can
339	        // tell that an incomplete key file may remain.
340	        std::cerr << "envelopefile: " << save.error << '\n';
341	        if (save.status == KeySaveStatus::kCleanupFailed) {
342	            std::cerr << "envelopefile: warning: " << save.removalWarning
343	                      << '\n';
344	        }
345	        return 1;
346	    }
347	
348	    // key is wiped here by the SecureBuffer destructor; its contents never
349	    // reach stdout, stderr, or any log.
350	    std::cout << "envelopefile: 32-byte key generated and saved to '"
351	              << outputPath << "'\n";
352	    return 0;
353	}
354	
355	}  // namespace
356	
357	int main(int argc, char* argv[]) {
358	    if (argc == 2 && std::string_view(argv[1]) == "--version") {
359	        std::cout << kVersionString;
360	        return 0;
361	    }
362	
363	    if (argc >= 2 && std::string_view(argv[1]) == "keygen") {
364	        return runKeygen(argc, argv);
365	    }
366	
367	    std::cerr << kUsage;
368	    return 2;
369	}
