        // Retry once if interrupted; simplest is to re-issue via a short loop.
        do {
            got = ::read(fd, &extra, 1);
        } while (got < 0 && errno == EINTR);
        if (got < 0) {
            error = "failed reading key file '" + path + "': " +
                    errnoDescription(errno);
            return false;
